const initialState={view:'home',location:'platform',found:[],interviewed:[],events:[],complete:false,wrong:0};
let state;try{state={...initialState,...JSON.parse(localStorage.getItem('arquivo09')||'{}'),view:'home'}}catch{state={...initialState}}
const app=document.getElementById('app');
const evidenceItems=()=>locations.flatMap(l=>l.clues.filter(c=>state.found.includes(c.id)).map(c=>({...c,source:l.name}))).concat(suspects.flatMap(s=>s.choices.filter(c=>state.interviewed.includes(s.id)).map(c=>c.evidence)));
const progress=()=>Math.round((state.found.length+state.interviewed.length)/(locations.reduce((n,l)=>n+l.clues.length,0)+suspects.length)*100);
function save(){localStorage.setItem('arquivo09',JSON.stringify(state))}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function setView(view){state.view=view;save();render()}
function navButton(id,icon,label,count=''){return `<button class="nav-btn ${state.view===id?'active':''}" data-view="${id}"><span class="nav-icon">${icon}</span>${label}<span class="nav-count">${count}</span></button>`}
function render(){const p=progress();app.innerHTML=`<aside class="sidebar"><div class="brand"><div class="brand-mark">09</div><div class="brand-name">ARQUIVO<span>UNIDADE DE CASOS FRIOS</span></div></div><div class="section-label">CASO ATIVO</div><div class="case-chip"><div class="eyebrow">CASO Nº 09 — ABERTO</div><b>O Último Trem</b><small>Estação Central · 14 out 1998</small></div><div class="section-label">INVESTIGAÇÃO</div><nav class="nav-list">${navButton('home','⌂','Visão geral')}${navButton('locations','⌖','Locais',`${locations.length}`)}${navButton('evidence','▤','Evidências',`${evidenceItems().length}`)}${navButton('suspects','♙','Suspeitos',`${state.interviewed.length}/3`)}${navButton('board','⌘','Quadro de pistas')}</nav><div class="sidebar-bottom"><div class="case-status"><div class="status-row"><span>PROGRESSO DO CASO</span><span>${p}%</span></div><div class="progress-track"><div class="progress-fill" style="width:${p}%"></div></div><div class="status-note">${state.complete?'Caso encerrado. Bom trabalho.':`${state.found.length} pistas · ${state.interviewed.length} depoimentos`}</div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">ARQUIVO / <span>CASO 09</span> / ${({home:'VISÃO GERAL',locations:'LOCAIS',scene:'INVESTIGAÇÃO',evidence:'EVIDÊNCIAS',suspects:'SUSPEITOS',board:'QUADRO DE PISTAS'})[state.view]||'VISÃO GERAL'}</div><div class="top-actions"><span class="day-pill">◷ &nbsp;14 OUT 1998</span><button class="sound-btn" id="resetBtn" aria-label="Reiniciar caso" title="Reiniciar caso">↺</button></div></header><div class="content">${viewContent()}<div class="footer-note">ARQUIVO 09 &nbsp;·&nbsp; DIVISÃO DE INVESTIGAÇÃO &nbsp;·&nbsp; EST. 1987</div></div></main><nav class="mobile-nav">${[['home','⌂','INÍCIO'],['locations','⌖','LOCAIS'],['evidence','▤','PISTAS'],['suspects','♙','PESSOAS'],['board','⌘','DOSSIÊ']].map(([id,ic,n])=>`<button data-view="${id}" class="${state.view===id?'active':''}"><span>${ic}</span><span>${n}</span></button>`).join('')}</nav><div id="modalRoot"></div><div class="toast" id="toast"></div>`;bind();}
function viewContent(){switch(state.view){case'locations':return locationsView();case'scene':return sceneView();case'evidence':return evidenceView();case'suspects':return suspectsView();case'board':return boardView();default:return homeView()}}
function homeView(){return `<section class="view active"><div class="hero"><div class="hero-art"></div><div class="hero-stamp">ARQUIVO ABERTO<br>CASO Nº 09</div><div class="hero-copy"><div class="kicker">UMA INVESTIGAÇÃO INTERATIVA</div><h1>O Último<br>Trem</h1><p>Uma morte. Três suspeitos. E uma estação que guarda mais segredos do que passageiros.</p><button class="primary-btn" data-view="locations">${state.found.length?'CONTINUAR INVESTIGAÇÃO':'INICIAR INVESTIGAÇÃO'} &nbsp;→</button></div></div><div class="section-head"><h2>O caso em suas mãos</h2><p>INVESTIGUE NO SEU RITMO</p></div><div class="overview-grid"><article class="brief-card"><div class="card-kicker">RELATÓRIO INICIAL &nbsp; / &nbsp; 14 OUT 1998</div><h3>Uma noite sem testemunhas.</h3><p>Helena Duarte, repórter investigativa, foi encontrada morta na plataforma 3 pouco antes da meia-noite. O relógio da estação parou às 23h17. O último trem partiu vazio. A polícia local classificou como acidente — mas há sinais de que alguém preparou a cena.</p><div class="meta-row"><div class="meta-item"><span>VÍTIMA</span><b>Helena Duarte, 34</b></div><div class="meta-item"><span>LOCAL</span><b>Estação Central</b></div><div class="meta-item"><span>STATUS</span><b style="color:var(--acid)">${state.complete?'RESOLVIDO':'EM ABERTO'}</b></div></div></article><article class="activity-card"><div class="activity-title"><h3>Notas do caso</h3><span class="live-dot"></span></div>${state.events.length?state.events.slice(-3).reverse().map(e=>`<div class="activity-item"><i>✳</i><span>${esc(e)}</span></div>`).join(''):'<div class="activity-empty">Nenhuma pista registrada ainda.<br>Explore os locais e converse com as pessoas envolvidas.</div>'}</article></div></section>`}
function viewHead(kicker,title,desc,action=''){return `<div class="view-head"><div><div class="kicker">${kicker}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function locationsView(){return `<section class="view active">${viewHead('CAMPO / ESTAÇÃO CENTRAL','Locais','Cada canto da estação conta uma história. Procure com atenção.')}<div class="location-grid">${locations.map((l,i)=>{const count=l.clues.filter(c=>state.found.includes(c.id)).length;return `<article class="location-card" data-location="${l.id}"><div class="location-thumb"><img src="${l.image}" alt=""><span>${l.type}</span></div><div class="location-info"><h3>${l.name}</h3><p>${l.place}</p><div class="location-foot"><span>PISTAS ENCONTRADAS</span><b>${count} / ${l.clues.length} &nbsp; →</b></div></div></article>`}).join('')}</div></section>`}
function sceneView(){const l=locations.find(x=>x.id===state.location)||locations[0];return `<section class="view active">${viewHead(l.type,l.name,l.place,`<button class="secondary-btn" data-view="locations">← &nbsp; TODOS OS LOCAIS</button>`)}<div class="scene-layout"><div><div class="scene-image"><img src="${l.image}" alt="${l.name}"><div class="scene-caption"><b>${l.name}</b><span>${l.place.toUpperCase()}</span></div></div><div class="scene-description">${l.desc}<br><span style="color:#d5f073">Investigue os itens abaixo para registrar evidências no seu dossiê.</span></div></div><div><div class="section-head" style="margin:0 0 11px"><h2 style="font-size:18px">Pontos de interesse</h2><p>${l.clues.filter(c=>state.found.includes(c.id)).length}/${l.clues.length} ANALISADOS</p></div><div class="clue-list">${l.clues.map((c,i)=>{const found=state.found.includes(c.id);return `<button class="clue-card ${found?'found':''}" data-clue="${c.id}"><span class="clue-symbol">${found?'✓':c.icon}</span><span><b>${c.name}</b><small>${found?'Evidência registrada':c.desc}</small></span><span class="clue-state">${found?'✓':'ANALISAR'}</span></button>`}).join('')}</div></div></div></section>`}

