omplete?`<div class="report-card"><div class="card-kicker">CASO ENCERRADO · 15 OUT 1998</div><h3>Justiça, enfim.</h3><p>Elias Moura foi preso ao amanhecer. A prata roubada foi recuperada no depósito dos trilhos. Seu relatório levou à reabertura de outros quatro casos arquivados na estação.</p><div class="report-actions"><button class="secondary-btn" data-view="evidence">REVER EVIDÊNCIAS</button><button class="secondary-btn" id="resetFromReport">NOVO CASO ↺</button></div></div>`:''}</section>`}
function showModal(title,kicker,body){const root=document.getElementById('modalRoot');root.innerHTML=`<div class="overlay" data-dismiss="true"><section class="modal" role="dialog" aria-modal="true"><div class="modal-top"><div class="kicker">${kicker}</div><button class="modal-close" aria-label="Fechar">×</button></div><h2>${title}</h2>${body}</section></div>`;root.querySelector('.modal-close').onclick=()=>root.innerHTML='';root.querySelector('.overlay').onclick=e=>{if(e.target.dataset.dismiss)root.innerHTML=''};}
function toast(msg){const el=document.getElementById('toast');if(!el)return;el.textContent=msg;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
function investigate(id){let clue=locations.flatMap(l=>l.clues).find(c=>c.id===id);if(!clue)return;if(!state.found.includes(id)){state.found.push(id);state.events.push(`Evidência coletada: ${clue.name}.`);save();render()}showModal(clue.name,'EVIDÊNCIA REGISTRADA',`<p>${clue.detail}</p><div class="modal-result">REGISTRADA NO DOSSIÊ &nbsp;·&nbsp; ${clue.source||locations.find(l=>l.clues.includes(clue))?.name||'ESTAÇÃO CENTRAL'}</div><div style="margin-top:19px"><button class="primary-btn modal-done">VOLTAR À INVESTIGAÇÃO</button></div>`);document.querySelector('.modal-done').onclick=()=>document.getElementById('modalRoot').innerHTML=''}
function interview(id){const s=suspects.find(x=>x.id===id);if(!s)return;if(state.interviewed.includes(id)){const answer=s.choices[0];showModal(s.name,s.role,`<div class="dialogue-box">${answer.result}</div><div class="modal-result">${answer.evidence.name} — registrada no dossiê.</div>`);return}showModal(s.name,s.role,`<p>${s.bio}</p><div class="dialogue-box">${s.question}</div><div class="choice-list">${s.choices.map((c,i)=>`<button class="choice-btn" data-answer="${id}:${i}">${c.text}</button>`).join('')}</div>`);document.querySelectorAll('[data-answer]').forEach(btn=>btn.onclick=()=>{const choice=s.choices[Number(btn.dataset.answer.split(':')[1])];state.interviewed.push(id);state.events.push(`Depoimento registrado: ${s.name}.`);save();render();showModal('Uma peça se encaixa…','DEPOIMENTO REGISTRADO',`<div class="dialogue-box">${choice.result}</div><div class="modal-result">NOVA EVIDÊNCIA &nbsp;·&nbsp; ${choice.evidence.name}</div><div style="margin-top:19px"><button class="primary-btn modal-done">CONTINUAR</button></div>`);document.querySelector('.modal-done').onclick=()=>document.getElementById('modalRoot').innerHTML=''})}
function submitAccusation(){const who=document.getElementById('culprit')?.value,motive=document.getElementById('motive')?.value,proof=document.getElementById('proof')?.value;if(!who||!motive||!proof){toast('Preencha as três partes do relatório.');return}if(who==='elias'&&motive==='robbery'&&proof==='ledger'){state.complete=true;state.events.push('Caso solucionado: Elias Moura foi identificado como culpado.');save();render();showModal('Caso encerrado.','CONCLUSÃO CORRETA',`<p>O livro de despacho prova que Elias movimentou as caixas roubadas. Nuno confirmou o esquema, e Helena seria a próxima a denunciá-lo. Elias a matou para silenciá-la — mas não conseguiu apagar todas as pistas.</p><div class="modal-result">CULPADO: ELIAS MOURA &nbsp;·&nbsp; MOTIVO: ENCOBRIR O ROUBO<br>EVIDÊNCIA-CHAVE: LIVRO DE DESPACHO</div><div style="margin-top:19px"><button class="primary-btn modal-done">VER RELATÓRIO FINAL</button></div>`);document.querySelector('.modal-done').onclick=()=>{document.getElementById('modalRoot').innerHTML='';setView('board')};return}state.wrong++;save();const message=who!=='elias'?'Essa pessoa não tinha acesso às áreas restritas. Reavalie os horários e as pistas.':motive!=='robbery'?'O motivo não combina com as caixas sem registro e o telegrama de Helena.':'O livro de despacho conecta Elias diretamente às caixas roubadas. Procure-o na sala do chefe.';showModal('Há algo que não fecha.','CONCLUSÃO INCOMPLETA',`<p>${message}</p><div class="modal-result">Uma acusação precipitada pode deixar o culpado escapar. Reexamine as pistas antes de tentar novamente.</div><div style="margin-top:19px"><button class="secondary-btn modal-done">VOLTAR AO QUADRO</button></div>`);document.querySelector('.modal-done').onclick=()=>document.getElementById('modalRoot').innerHTML=''}
function resetCase(){if(confirm('Reiniciar a investigação? Todo o progresso deste caso será apagado.')){localStorage.removeItem('arquivo09');state={...initialState,found:[],interviewed:[],events:[],complete:false,wrong:0};render()}}
function bind(){document.querySelectorAll('[data-view]').forEach(el=>el.addEventListener('click',()=>setView(el.dataset.view)));document.querySelectorAll('[data-location]').forEach(el=>el.addEventListener('click',()=>{state.location=el.dataset.location;setView('scene')}));document.querySelectorAll('[data-clue]').forEach(el=>el.addEventListener('click',()=>investigate(el.dataset.clue)));document.querySelectorAll('[data-interview]').forEach(el=>el.addEventListener('click',()=>interview(el.dataset.interview)));document.getElementById('submitAccusation')?.addEventListener('click',submitAccusation);document.getElementById('resetBtn')?.addEventListener('click',resetCase);document.getElementById('resetFromReport')?.addEventListener('click',resetCase);document.querySelector('.sound-btn')?.addEventListener('dblclick',()=>toast('Este arquivo não contém áudio.'));}
render();

